//! Schema names and fields match the installed Hecate 1.3.444.761 vault.
use anyhow::Result;
use rusqlite::Connection;

pub fn initialize(db: &Connection) -> Result<()> {
    db.execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL;
        CREATE TABLE IF NOT EXISTS evaluator_systems(id INTEGER PRIMARY KEY AUTOINCREMENT,fid INTEGER NOT NULL,id64 INTEGER NOT NULL,dtepoch INTEGER NOT NULL,name TEXT NOT NULL,UNIQUE(fid,id64) ON CONFLICT REPLACE);
        CREATE TABLE IF NOT EXISTS evaluator(id INTEGER PRIMARY KEY AUTOINCREMENT,fid INTEGER NOT NULL,id64 INTEGER NOT NULL,bodyid INTEGER NOT NULL,value INTEGER NOT NULL,dtepoch INTEGER NOT NULL,bodyname TEXT NOT NULL,UNIQUE(fid,id64,bodyid) ON CONFLICT REPLACE);
        CREATE TABLE IF NOT EXISTS bioinsights_unsold(id INTEGER PRIMARY KEY AUTOINCREMENT,fid INTEGER NOT NULL,id64 INTEGER NOT NULL,bodyid INTEGER NOT NULL,dtepoch INTEGER NOT NULL,bioname TEXT NOT NULL,species INTEGER NOT NULL,basevalue INTEGER NOT NULL,bodyname TEXT NOT NULL,UNIQUE(fid,id64,bodyid,species) ON CONFLICT REPLACE);
        CREATE TABLE IF NOT EXISTS bioinsights_unsold_bonus(id INTEGER PRIMARY KEY AUTOINCREMENT,fid INTEGER NOT NULL,id64 INTEGER NOT NULL,bodyid INTEGER NOT NULL,species INTEGER NOT NULL,bonus INTEGER NOT NULL,UNIQUE(fid,id64,bodyid,species) ON CONFLICT REPLACE);
        CREATE TABLE IF NOT EXISTS census(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,lastseenepoch INTEGER NOT NULL,lastseensystem INTEGER NOT NULL,count INTEGER NOT NULL DEFAULT 1,UNIQUE(name));
        CREATE TABLE IF NOT EXISTS commanders(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,fid INTEGER NOT NULL,lastseenepoch INTEGER NOT NULL,UNIQUE(fid,name));
        CREATE TABLE IF NOT EXISTS syslookup_000(id INTEGER PRIMARY KEY AUTOINCREMENT,id64 INTEGER NOT NULL,name TEXT NOT NULL,x REAL NOT NULL,y REAL NOT NULL,z REAL NOT NULL,population INTEGER,UNIQUE(id64) ON CONFLICT REPLACE);
        CREATE TABLE IF NOT EXISTS pp_merits_000(id INTEGER PRIMARY KEY,system INTEGER NOT NULL,targetsystem INTEGER NOT NULL,fid INTEGER NOT NULL,power INTEGER NOT NULL,cycle INTEGER NOT NULL,session INTEGER NOT NULL,activity INTEGER NOT NULL,meritsgained INTEGER NOT NULL,totalmerits INTEGER NOT NULL,flags INTEGER NOT NULL,dtepoch INTEGER NOT NULL);
        CREATE INDEX IF NOT EXISTS evaluator_fid_idx ON evaluator(fid);
        CREATE INDEX IF NOT EXISTS bioinsights_unsold_fid_idx ON bioinsights_unsold(fid);
        CREATE INDEX IF NOT EXISTS pp_merits_fid_power_idx ON pp_merits_000(fid,power,cycle);")?;
    Ok(())
}
